import { type CnOptions, cn as mergeClasses } from "tailwind-variants";

export function cn(...classes: CnOptions): string {
  return mergeClasses(...classes) ?? "";
}

"use client";

import { createContext, type ReactNode, useContext } from "react";

export type Size = "xs" | "sm" | "md" | "lg" | "xl";

const SizeContext = createContext<Size | undefined>(undefined);

export function useSize(size?: Size) {
  const inherited = useContext(SizeContext);
  return size ?? inherited;
}

export function SizeProvider({
  size,
  children,
}: {
  size: Size | undefined;
  children: ReactNode;
}) {
  return <SizeContext value={size}>{children}</SizeContext>;
}

"use client";

import { LayoutGroup } from "motion/react";
import { useId } from "react";
import {
  ToggleButtonGroup as AriaToggleButtonGroup,
  composeRenderProps,
  type ToggleButtonGroupProps,
} from "react-aria-components";
import { cn } from "./utils";
import { type Size, SizeProvider, useSize } from "./size";

export const groupFrameStyles = {
  xs: "gap-0.5 rounded-md p-0.5",
  sm: "",
  md: "",
  lg: "",
  xl: "rounded-xl",
} satisfies Record<Size, string>;

export function ToggleButtonGroup({
  className,
  size: sizeProp,
  ...props
}: ToggleButtonGroupProps & { size?: Size }) {
  const groupId = useId();
  const size = useSize(sizeProp);
  return (
    <SizeProvider size={size}>
      <LayoutGroup id={groupId}>
        <AriaToggleButtonGroup
          {...props}
          data-slot="toggle-button-group"
          data-size={size}
          className={composeRenderProps(className, (className) =>
            cn(
              "inline-flex w-fit max-w-full flex-wrap gap-1 rounded-lg border border-border bg-secondary p-1 data-[orientation=vertical]:flex-col data-[orientation=vertical]:[--touch-target:calc(100%+0.25rem)]",
              size && groupFrameStyles[size],
              className,
            ),
          )}
        />
      </LayoutGroup>
    </SizeProvider>
  );
}

"use client";

import {
  Toolbar as AriaToolbar,
  composeRenderProps,
  SeparatorContext,
  ToggleButtonGroupContext,
  type ToolbarProps,
} from "react-aria-components";
import { cn } from "./utils";
import { type Size, SizeProvider, useSize } from "./size";
import { groupFrameStyles } from "./toggle-button-group";

export function Toolbar({
  className,
  size: sizeProp,
  ...props
}: ToolbarProps & { size?: Size }) {
  const orientation = props.orientation ?? "horizontal";
  const size = useSize(sizeProp);
  return (
    <SizeProvider size={size}>
      <ToggleButtonGroupContext.Provider value={{ orientation }}>
        <SeparatorContext.Provider
          value={{
            orientation:
              orientation === "horizontal" ? "vertical" : "horizontal",
          }}
        >
          <AriaToolbar
            {...props}
            data-slot="toolbar"
            data-size={size}
            className={composeRenderProps(className, (className) =>
              cn(
                "flex w-fit max-w-full flex-wrap items-center gap-1 rounded-lg border border-border bg-card p-1 shadow-[var(--shadow-card)] data-[orientation=vertical]:flex-col data-[orientation=vertical]:items-stretch data-[orientation=vertical]:[--touch-target:calc(100%+0.25rem)] [&_[data-slot=toggle-button-group]]:border-0 [&_[data-slot=toggle-button-group]]:bg-transparent [&_[data-slot=toggle-button-group]]:p-0",
                "[&_[data-variant=segmented][data-hovered]:not([data-selected])]:bg-muted [&_[data-variant=segmented][data-pressed]:not([data-selected])]:bg-muted",
                size && groupFrameStyles[size],
                className,
              ),
            )}
          />
        </SeparatorContext.Provider>
      </ToggleButtonGroupContext.Provider>
    </SizeProvider>
  );
}
